import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
const repo=process.cwd();
const startedAt=new Date().toISOString();
const sha=value=>createHash('sha256').update(value).digest('hex');
const inputPaths=['src/components/PoemLesson.tsx','src/components/Recitation.tsx','src/components/TodayConnection.tsx','src/components/Quiz.tsx','src/components/PoetryScene.tsx','src/data/rewards.ts','src/App.tsx','src/components/Libraries.tsx','src/components/Parents.tsx','src/components/WordPlay.tsx','src/store.ts','src/types.ts','src/tablet-viewport.ts','src/data/poems.json','src/data/today-connections.json','src/styles.css','src/ipad-layout.css','src/poem-viewport.css'];
const inputSources=Object.fromEntries(inputPaths.map(path=>[path,{sha256:sha(readFileSync(repo+'/'+path)),bytes:readFileSync(repo+'/'+path).length}]));
const require=createRequire(repo+'/package.json');
const {buildSync}=require('esbuild');
const {chromium,webkit}=require('@playwright/test');
const poems=JSON.parse(readFileSync(repo+'/src/data/poems.json','utf8'));
const css=['styles.css','ipad-layout.css','poem-viewport.css'].map(p=>readFileSync(repo+'/src/'+p,'utf8')).join('\n');
const fixture=buildSync({stdin:{contents:`import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {flushSync} from 'react-dom';import PoemLesson from './src/components/PoemLesson';import {createProfile,initialProgress} from './src/store';import poems from './src/data/poems.json';let sequence=0;const root=createRoot(document.getElementById('root'));function Harness({index,stage,recitation}){const poem=poems[index];const [profile,update]=useState(()=>{const p=createProfile('诗词视口测试');p.settings.sound=false;p.settings.music=false;p.poems[poem.id]={...initialProgress(),stage,activityDone:true,listenedLines:poem.lines.map((_,i)=>i),recitation};return p;});window.latestProfile=profile;return <PoemLesson poem={poem} profile={profile} onUpdate={update} onSpeak={async text=>{window.spoken.push(text);await new Promise(r=>setTimeout(r,5));return true;}} onPrepare={()=>{}} onStop={()=>{}} onClose={()=>{}} onZoo={()=>{}}/>;}window.spoken=[];window.mountPoem=(index,stage,recitation)=>flushSync(()=>root.render(<Harness key={sequence++} index={index} stage={stage} recitation={recitation}/>));`,resolveDir:repo,loader:'tsx'},bundle:true,write:false,format:'iife',target:'es2020',jsx:'automatic',loader:{'.css':'empty'},define:{'process.env.NODE_ENV':'"production"'},logLevel:'silent'}).outputFiles[0].text;
const html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+css+'</style><div id="root"></div><script>'+fixture.replace(/<\/script/gi,'<\\/script')+'</script>';
const report={startedAt,inputSources,inspectedScreens:0,runtimeErrors:[],audit:'All 300 poetry courses at the lowest tablet viewport, using the actual components with mock narration',viewport:{width:1180,height:720},courses:[],issues:[],limitations:['Isolated Chromium layout and DOM interaction fixture, not a physical iPad.', 'Narration is mocked; this does not test actual audio.', 'Source texts are compared across explicit pages; long poem stages and touch are separately checked in the application tests.']};
async function settle(page){await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));}
async function mount(page,index,stage,recitation){await page.evaluate(({index,stage,recitation})=>window.mountPoem(index,stage,recitation),{index,stage,recitation});await settle(page);}
async function inspect(page,label){report.inspectedScreens++;const result=await page.evaluate(()=>{const h=innerHeight,w=innerWidth;const outside=[...document.querySelectorAll('.poetry-overlay button,.poetry-overlay a,.poetry-overlay p,.poetry-overlay h2,.poetry-overlay h3')].filter(e=>e.getClientRects().length).map(e=>{const r=e.getBoundingClientRect();return{tag:e.tagName,text:e.textContent?.trim().slice(0,75),top:r.top,bottom:r.bottom,left:r.left,right:r.right};}).filter(r=>r.top<-.5||r.bottom>h+.5||r.left<-.5||r.right>w+.5);const scrollers=[...document.querySelectorAll('.poetry-overlay,.poetry-overlay *')].filter(e=>{const s=getComputedStyle(e);return /auto|scroll/.test(s.overflowY)&&e.scrollHeight>e.clientHeight+1;}).map(e=>e.className);return {height:h,documentHeight:document.documentElement.scrollHeight,overlayHeight:document.querySelector('.poetry-overlay').scrollHeight,outside,scrollers};});const panels=await page.evaluate(()=>[...document.querySelectorAll('.lesson-content,.poem-reading,.poem-paper,.poem-lines,.poem-story,.poem-today,.line-order,.ordered-lines,.line-options,.recite-final,.hidden-poem')].filter(e=>e.getClientRects().length&&e.scrollHeight>e.clientHeight+2).map(e=>({className:e.className,excess:e.scrollHeight-e.clientHeight})));result.panels=panels;if(panels.length||result.outside.length||result.scrollers.length||result.documentHeight>result.height+1||result.overlayHeight>result.height+1)report.issues.push({label,...result});return result;}

const browser=await chromium.launch({channel:'chrome'});report.environment={node:process.version,platform:process.platform,browser:'Chromium',browserVersion:browser.version(),channel:'chrome',physicalDevice:false,deviceScaleFactor:1,isMobile:true,hasTouch:true,date:new Date().toLocaleDateString('sv-SE'),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};report.renderedFixtureSha256=sha(html);const page=await browser.newPage({viewport:report.viewport,deviceScaleFactor:1,isMobile:true,hasTouch:true});page.on('pageerror',error=>report.runtimeErrors.push(error.message));await page.route('**/poem-viewport-fixture',route=>route.fulfill({contentType:'text/html',body:html}));await page.goto('http://127.0.0.1:5173/poem-viewport-fixture');await page.waitForFunction(()=>typeof window.mountPoem==='function');
async function inspectPages(label,nextName,readText){const result=[];let count=0;for(;;){await inspect(page,label+'/page-'+(++count));if(readText)result.push(...await readText());const next=page.getByRole('button',{name:nextName,exact:true});if(!await next.count()||!await next.isEnabled())break;await next.click();await settle(page);if(count>30)throw Error('Pagination did not terminate '+label);}return result;}
for(const [index,poem]of poems.entries()){
 const initialIssues=report.issues.length;
 await mount(page,index,0);const reading=await inspectPages(poem.id+'/reading','下一页诗句',()=>page.locator('.poem-line').evaluateAll(nodes=>nodes.map(n=>{const copy=n.cloneNode(true);copy.querySelectorAll('rt').forEach(rt=>rt.remove());return copy.textContent;})));if(JSON.stringify(reading)!==JSON.stringify(poem.lines))report.issues.push({label:poem.id+'/reading-content',reading});
 await mount(page,index,1);for(const [part,title]of ['诗人是谁？','那时发生了什么？','诗里看见了什么？'].entries()){await page.getByRole('button',{name:title,exact:true}).click();await settle(page);const story=await inspectPages(poem.id+'/story-'+part,'下一页故事',async()=>[await page.locator('.poem-story-card p').textContent()]);const expected=[`${poem.dynasty}代的${poem.author}，写下了《${poem.title}》。`,poem.background,poem.interpretation.join(' ')][part];if(story.join('')!==expected)report.issues.push({label:poem.id+'/story-'+part+'-content',story});}
 await mount(page,index,2);await page.getByRole('button',{name:poem.question.options[poem.question.answer],exact:true}).click();await settle(page);await inspect(page,poem.id+'/quiz-feedback');
 await mount(page,index,3);await inspect(page,poem.id+'/practice');await page.getByRole('button',{name:'今天的小发现',exact:true}).click();await settle(page);await inspectPages(poem.id+'/discovery','下一页生活资料');
 await mount(page,index,4,{phase:0,chunk:0,selected:[0,1,2,3].slice(0,Math.min(4,poem.lines.length)),clozeRound:0});await inspect(page,poem.id+'/order-completed');
 await mount(page,index,4,{phase:1,chunk:0,selected:[],clozeRound:0});await inspect(page,poem.id+'/cloze');
 await mount(page,index,4,{phase:2,chunk:0,selected:[],clozeRound:0});await page.getByRole('button',{name:'看看提示',exact:true}).click();await page.getByRole('button',{name:'家长确认：孩子已尝试完整背诵',exact:true}).click();await settle(page);const recalled=await inspectPages(poem.id+'/recitation','下一页背诵诗句',()=>page.locator('.hidden-poem p').allTextContents());if(JSON.stringify(recalled)!==JSON.stringify(poem.lines))report.issues.push({label:poem.id+'/recitation-content',recalled});
 await mount(page,index,5);await page.getByRole('button',{name:poem.question.options[poem.question.answer],exact:true}).click();await settle(page);await inspect(page,poem.id+'/final-quiz-feedback');await page.getByRole('button',{name:'下一小题',exact:true}).click();await settle(page);await page.getByRole('button',{name:poem.author,exact:true}).click();await settle(page);await inspect(page,poem.id+'/author-quiz-feedback');
 await mount(page,index,6);await inspect(page,poem.id+'/completion');
 report.courses.push({id:poem.id,passed:report.issues.length===initialIssues,readingLines:reading.length,recitationLines:recalled.length,storyTextExact:!report.issues.slice(initialIssues).some(issue=>issue.label.startsWith(poem.id+'/story-')&&issue.label.endsWith('-content'))});if((index+1)%30===0)console.log(JSON.stringify({courses:index+1,issues:report.issues.length}));
}
await browser.close();report.finishedAt=new Date().toISOString();report.inputStability={unchanged:true,changedPaths:inputPaths.filter(path=>sha(readFileSync(repo+'/'+path))!==inputSources[path].sha256)};report.inputStability.unchanged=report.inputStability.changedPaths.length===0;report.scope={poemCourses:300,stages:[0,1,2,3,4,5,6],allReadingPages:true,allThreeStoryPartsAndTheirPages:true,allShownRecitationPages:true,recitationOrderingChunk:'first completed chunk',cloze:'initial line',quiz:'correct feedback in interpretation and both final rounds',todayConnection:'all four displayed data/source pages when current card exists'};report.componentSourceSummary={actualReactComponents:['PoemLesson','Recitation','TodayConnection','Quiz','PoetryScene'],adaptation:'Production TSX is bundled without source replacements. Only the parent harness substitutes narration/preloading/stopping and seeds disposable in-memory profiles.',persistedProductionDataModified:false,actualAudioPlayed:false};
const supplementaryPath='/tmp/ipad-long-profile-review.json';
if(existsSync(supplementaryPath)){
 const originalText=readFileSync(supplementaryPath,'utf8');const original=JSON.parse(originalText);
 report.supplementaryProfileReview={audit:'Twenty 16-character child names in the real App',originalReportSha256:sha(originalText),originalRuntimePath:supplementaryPath,runnerSha256:sha(readFileSync('/tmp/ipad-long-profile-review.mts')),scope:'52 DOM/viewport checks in Chromium and WebKit; Home, top profile menu and parent profile cards, with portrait/landscape rotation. All 20 full names were checked across explicit pages. Disposable localStorage; no real save or actual audio.',physicalDevice:false,actualAudioPlayed:false,profiles:20,nameCharacters:16,checks:original.results.length,failures:original.failures.length,runtimeErrors:original.errors.length,sourceHashesMatchFinal:Object.entries(original.inputHashes).every(([path,value])=>inputSources[path]?.sha256===value),saveComparison:'Full profiles array and activeId exactly match the fixture after navigation; only top-level savedAt is excluded.',originalReport:original};
}
report.readOnlySourceReview={goal:'Inspect tablet pagination, content access, rotation controls and unchanged save/audio wiring without changing product files.',paths:['src/App.tsx','src/components/Libraries.tsx','src/components/Parents.tsx','src/components/WordPlay.tsx','src/ipad-layout.css','src/tablet-viewport.ts'],completed:['Reviewed page slicing and min-clamped page labels/buttons, filter resets, retained navigation and parent sound/update callbacks.','Reviewed tablet completion-screen behavior and rotation breakpoint stability.','Confirmed pagination retains course content; all reading, story and shown recitation pages are compared with source strings.'],materialFinding:{component:'Parents',originalIssue:'Twenty legal 16-character names were joined into the backup confirmation, placing restore/retain buttons below the 1180x720 viewport.',evidence:'The original disposable-browser reproduction found document height 843px, restore button bottom 824.9px and retain button bottom 818px in Chromium and WebKit.',resolution:'Parent agent replaced the joined preview with explicit two-profile pages and fixed actions; final application backup/safe-area cases are checked in the independent iPad test report.'},additionalMaterialFindings:[],strengths:['Explicit pagination exposes long text without vertical scrolling.','The mock harness bundles actual production lesson components and checks original-string completeness.'],limits:['Source review is not a proof of every application state.','The supplementary 52 checks cover profile navigation; the backup fix and simulated safe-area application suite are independently recorded by the parent agent.'],nextFocus:'Physical iPad Safari and actual listening remain outside this simulated layout report.'};
report.runner={originalRuntimePath:fileURLToPath(import.meta.url),sha256:sha(readFileSync(fileURLToPath(import.meta.url))),source:readFileSync(fileURLToPath(import.meta.url),'utf8'),reproduce:'Extract runner.source to an .mjs file, then run node <file> with project root as cwd; uses project esbuild and Playwright plus installed Chrome. All browser contexts and profiles are disposable. The route supplies a local fixture, so no live app server is required.'};report.passed=report.courses.length===300&&report.courses.every(c=>c.passed)&&report.issues.length===0&&report.runtimeErrors.length===0&&report.inputStability.unchanged;const output=repo+'/scripts/verification/poem-one-screen-audit.json';writeFileSync(output,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({passed:report.passed,courses:report.courses.length,inspectedScreens:report.inspectedScreens,issues:report.issues.length,changedInputs:report.inputStability.changedPaths,firstIssues:report.issues.slice(0,4),report:output}));if(!report.passed)process.exitCode=1;
